// DUSK — «Звук пера»: аудио-семпл (data:audio/mpeg base64, ~155 КБ), вынесен из app.js (D-3).
// Грузится отдельным <script> ДО app.js, кладёт строку в window.PEN_ASSET.
// ВАЖНО (требование): фича работает ПОЛНОСТЬЮ ОФФЛАЙН из локального html через file://
// без сервера — _penLoad() декодирует эту base64-строку в памяти через atob (без fetch/сети).
window.PEN_ASSET = 'data:audio/mpeg;base64,';
